import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand, discardIds } from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const waterStatusScenarios=['poison-flow-ordinary','poison-flow-dedicated','freeze-ordinary','freeze-dedicated','freeze-recovery-ordinary','freeze-recovery-dedicated'] as const;
export type WaterStatusScenario=typeof waterStatusScenarios[number];
export function isWaterStatusScenario(name:string):name is WaterStatusScenario{return (waterStatusScenarios as readonly string[]).includes(name);}
export function waterStatusMode(name:WaterStatusScenario){const poison=name.startsWith('poison'),dedicated=name.endsWith('dedicated');return {card:poison?'a2-p12-r3c1':'a2-p12-r3c3',name:poison?'毒流':'氷結',poison,dedicated,use:poison?5:6,effect:poison?(dedicated?6:5):(dedicated?8:6),damage:poison?4:dedicated?8:4,modifier:poison?0:dedicated?-3:-1};}
export function makeWaterStatusScenario(name:WaterStatusScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:boolean;silenced?:boolean}={}){
 const m=waterStatusMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'凍気のアイエル');assignCharacter(s,b,options.silenced?'大神官ジル':'侍大将のシン');assignCharacter(s,c,options.silenced?'侍大将のシン':'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.magic_level=20+(options.level??m.use)-stats.magic_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;
 const card=takeCard(s,a,m.card),maai=takeCard(s,b,'a2-p07-r1c1'),evade=takeCard(s,b,'a2-p05-r3c1'),fate=takeCard(s,c,'命運凶変'),guard=options.follower?takeCard(s,b,'兵士'):null,teleport=options.follower?takeCard(s,b,'a2-p06-r1c1'):null,silence=options.silenced?takeCard(s,b,'沈黙'):null;for(const id of [a,b,c,d])trimHand(s,id,card,maai,evade,fate,...(guard?[guard]:[]),...(teleport?[teleport]:[]),...(silence?[silence]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(options.silenced||name.startsWith('freeze-recovery')?6:1)},r=transition(s,input,e);if(!r.ok)throw Error(`WATER_STATUS_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WATER_STATUS_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WATER_STATUS_IDS');}
 function advanceTo(target:string){for(let n=0;n<200;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('WATER_STATUS_TURN');}throw Error('WATER_STATUS_TURN_LIMIT');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(silence){act(a,{type:'PASS_ACTION'});advanceTo(b);act(b,{type:'ATTACK',cardInstanceId:silence,targetIds:[a],dedicated:false});advanceTo(a);if(!discardIds(s).includes(silence))throw Error('WATER_STATUS_SILENCE_PAYMENT');}if(name.startsWith('freeze-recovery')){act(a,{type:'ATTACK',cardInstanceId:card,targetIds:m.dedicated?[b,c]:[b],dedicated:m.dedicated});for(let n=0;n<300&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}if(!s.players[b]!.statuses?.some(t=>t.kind==='stopped'))throw Error('WATER_STATUS_STOP_FIXTURE');}return s;
}
